/**
 * Candidate ordering for assignment.
 *
 * `Directory.query` returns people in seed order, so the plain resolver hands
 * every instance of a workflow to the same first person. These strategies order
 * the candidates before `limit` is applied, so the choice is about *who among
 * the eligible*, never about who is eligible — presence and role filtering stay
 * in the query.
 */
import type { AssigneeSpec } from '../../../dsl/types.ts';
import type { Balancer } from './init.ts';
import type { WorkflowInstance } from './state.ts';
import { DEFAULT_ORGANIZATION_ID } from './identity.ts';

/**
 * A step counts as load when someone actually holds it: actionable now
 * (`status: true`) and not yet resolved (`state: 'open'`). A dormant step is
 * work that has not arrived, and a completed/rejected one is work already put
 * down — counting either would spread new work away from people who are
 * simply further along.
 */
export function openLoad(instances: WorkflowInstance[]): Map<string, number> {
  const load = new Map<string, number>();
  for (const instance of instances) {
    if (instance.terminal) continue;
    for (const step of instance.steps) {
      if (!step.status || step.state !== 'open') continue;
      for (const id of step.assignee) load.set(id, (load.get(id) ?? 0) + 1);
    }
  }
  return load;
}

export class WorkloadBalancer implements Balancer {
  /** Rotation cursors for round_robin, keyed per step template. */
  private cursors = new Map<string, number>();

  private readonly instances: () => WorkflowInstance[]; constructor(instances: () => WorkflowInstance[] = () => []) { this.instances = instances; }

  /**
   * Bind a request-consistent persistence snapshot while sharing round-robin
   * cursors across requests. The Mongo adapter cannot expose a synchronous
   * global list to the core resolver.
   */
  view(instances: WorkflowInstance[]): Balancer {
    return {
      order: (candidates, spec, key, organizationId) =>
        this.orderFrom(instances, candidates, spec, key, organizationId),
    };
  }

  order(
    candidates: string[],
    spec: AssigneeSpec,
    key = '',
    organizationId = DEFAULT_ORGANIZATION_ID,
  ): string[] {
    return this.orderFrom(this.instances(), candidates, spec, key, organizationId);
  }

  private orderFrom(
    instances: WorkflowInstance[],
    candidates: string[],
    spec: AssigneeSpec,
    key = '',
    organizationId = DEFAULT_ORGANIZATION_ID,
  ): string[] {
    switch (spec.strategy) {
      case 'least_loaded': {
        const load = openLoad(instances.filter((i) => i.organization_id === organizationId));
        // stable sort on load, so equal load keeps directory order and the
        // result stays reproducible for the same inputs
        return [...candidates].sort((a, b) => (load.get(a) ?? 0) - (load.get(b) ?? 0));
      }
      case 'round_robin': {
        if (candidates.length === 0) return candidates;
        const at = this.cursors.get(key) ?? 0;
        this.cursors.set(key, at + 1);
        const pivot = at % candidates.length;
        return [...candidates.slice(pivot), ...candidates.slice(0, pivot)];
      }
      default:
        return candidates;
    }
  }
}
